from test_bufftap import test,tests
setup="""
local B=BuffTap; context='solo'
IsInRaid=function() return context=='raid' end
IsInGroup=function() return context~='solo' end
GetNumSubgroupMembers=function() return context=='solo' and 0 or 2 end
B:Refresh()
"""
def case(name,code):test(name,setup+code)
case('Solo is baseline without a master toggle',"B:SyncSituation(); assert(B.db.situationSettings.version==2 and B.situationCurrent=='solo' and B:Preference('buffs')==B.db.buffs)")
for ctx in ['solo','party','raid']:
 case('Detect '+ctx,"context='"+ctx+"'; assert(B:DetectSituation()=='"+ctx+"')")
for size in [1,5,10,20,25,30,40]:
 case('Raid detection independent of size '+str(size),"context='raid'; GetNumGroupMembers=function() return "+str(size)+" end; assert(B:DetectSituation()=='raid')")
for kind in ['pvp','arena']:
 case(kind+' uses Solo baseline',"B:SetSituationValue('raid','buffs','buffs',false,'motw'); context='raid'; IsInInstance=function() return true,'"+kind+"' end; refresh(); assert(B.situationCurrent=='pvp' and B:Enabled(B:FindBuff('motw')))")
for result in ["error('unavailable')","return {secret=true}","return nil"]:
 case('Unavailable group state safe '+result,"IsInRaid=function() "+result+" end; B:SyncSituation(); assert(B.situationCurrent=='unknown' and B:Enabled(B:FindBuff('motw')))")
case('Party weapon edit leaves other fields inherited',"B.db.weaponChoices.main='old'; B:SetSituationValue('party','weapons','weaponSeconds',120); B:SetSituationValue('solo','weapons','weaponMainHand',false); local v=B:SituationPreview('party','weapons'); assert(v.weaponSeconds==120 and v.weaponMainHand==false and B:SituationPreview('raid','weapons').weaponSeconds==B.db.weaponSeconds)")
case('Sparse buff edits inherit later Solo changes',"B:SetSituationValue('party','buffs','buffs',false,'motw'); B:SetSituationValue('solo','buffs','buffs',false,'thorns'); local p=B:SituationPreview('party','buffs'); assert(p.buffs.motw==false and p.buffs.thorns==false and B.db.buffs.motw==nil)")
case('Party and Raid inherit independently',"B:SetSituationValue('party','buffs','seconds',90); B:SetSituationValue('solo','buffs','seconds',60); assert(B:SituationPreview('party','buffs').seconds==90 and B:SituationPreview('raid','buffs').seconds==60)")
case('False scalar remains a real override',"B.db.weaponReminder=true; B:SetSituationValue('party','weapons','weaponReminder',false); context='party'; refresh(); assert(B:Preference('weaponReminder')==false and B.db.weaponReminder)")
case('Explicit timing default masks inherited per-buff value',"B.db.buffSeconds.motw=30; B:SetSituationValue('party','buffs','seconds',90); B:SetSituationValue('party','buffs','buffSeconds',nil,'motw'); context='party'; refresh(); assert(B:RebuffSeconds(B:FindBuff('motw'))==90 and B.db.buffSeconds.motw==30); B:InitDB(); assert(B:RebuffSeconds(B:FindBuff('motw'))==90)")
case('Reset restores complete inheritance',"B:SetSituationValue('party','buffs','buffs',false,'motw'); B:CustomizeSituation('party','buffs',false); assert(not B:SituationValues('party','buffs') and B:SituationPreview('party','buffs')==B.db)")
case('Matching Solo value removes override',"B:SetSituationValue('party','buffs','seconds',90); B:SetSituationValue('party','buffs','seconds',B.db.seconds); assert(not B:SituationValues('party','buffs'))")
custom="B:SetSituationValue('party','buffs','buffs',false,'motw'); "
case('Joining and leaving changes actual queue',custom+"context='party'; refresh(); assert(B.action.id==467); context='solo'; refresh(); assert(B.action.id==5232)")
case('Inactive editor does not activate Raid',"B:Options(); B.contextControls.buffs.buttons.raid.scripts.OnClick(); assert(B:EditorContext('buffs')=='raid' and B.situationCurrent=='solo' and B.action.id==5232)")
case('Real checkbox edits only its selected context',"B:Options(); B.contextControls.buffs.buttons.party.scripts.OnClick(); for _,row in ipairs(B.options.buffRows) do if row.def.key=='motw' then row.check:SetChecked(false); row.check.scripts.OnClick(row.check) end end; assert(B:SituationValues('party','buffs').buffs.motw==false and B.db.buffs.motw==nil); context='party'; refresh(); assert(B.action.id==467)")
case('Priority movement edits selected context',"B:Options(); B.contextControls.buffs.buttons.party.scripts.OnClick(); B:MoveBuffPriority('thorns','motw'); assert(B:SituationPreview('party','buffs').priorities.thorns==1 and B.db.priorities.thorns==nil)")
case('Stale hardware click refuses previous context',custom+"context='party'; B.button.scripts.PreClick(nil,'LeftButton',true); assert(not B.action and not B.button.attrs.type1); advance(.1); assert(B.action.id==467)")
case('Combat context changes defer secure configuration',custom+"B:SyncSituation(); combat=true; safety('blocked'); context='party'; B.events.scripts.OnEvent(nil,'GROUP_ROSTER_UPDATE'); assert(B.situationCurrent=='solo' and B.situationDeferred); combat=false; safety('ready'); B.events.scripts.OnEvent(nil,'PLAYER_REGEN_ENABLED'); assert(B.situationCurrent=='party' and B.action.id==467)")
case('Config writes refused during combat',"combat=true; assert(not B:SetSituationValue('party','buffs','seconds',120)); assert(not B:CustomizeSituation('party','buffs',false))")
case('Application and replacement permissions remain common',"assert(not B:SetSituationValue('party','weapons','weaponApply',true)); assert(not B:SetSituationValue('party','weapons','weaponReplace',true)); assert(not B.db.weaponApply and not B.db.weaponReplace)")
case('Existing group plans remain outside override schema',"B.db.blessingAssignments=true; B.db.raidGroups[4]=false; assert(not B:SetSituationValue('raid','buffs','blessingAssignments',false)); assert(B.db.blessingAssignments and B.db.raidGroups[4]==false)")
case('Disabled legacy drafts preserved without activation',"B.db.situationSettings={version=1,enabled=false,class='DRUID',party={buffs={buffs={motw=false}}}}; B:InitDB(); assert(B.db.situationLegacyBackup.party.buffs.buffs.motw==false and not B:SituationValues('party','buffs'))")
case('Enabled legacy Solo promoted and Party differences retained',"B.db.situationSettings={version=1,enabled=true,class='DRUID',solo={buffs={seconds=60}},party={buffs={seconds=90}}}; B:InitDB(); assert(B.db.seconds==60 and B:SituationPreview('party','buffs').seconds==90 and B.db.situationSettings.version==2)")
case('Shared profile switch preserves character overrides',custom+"B:CreateSettingsProfile('Other',false); assert(B:SituationValues('party','buffs').buffs.motw==false)")
case('Explicit same-class profile copy includes overrides',custom+"B:SaveClassSetup(); local source=B.profileDB:GetCurrentProfile(); local character=B.profileDB.keys.char; B:CreateSettingsProfile('Other',false); B:CustomizeSituation('party','buffs',false); assert(B:CopySettingsProfile(source,character)); assert(B:SituationValues('party','buffs').buffs.motw==false)")
case('Shared-only profile copy leaves overrides intact',custom+"B:SaveClassSetup(); local source=B.profileDB:GetCurrentProfile(); B:CreateSettingsProfile('Other',false); assert(B:CopySettingsProfile(source)); assert(B:SituationValues('party','buffs').buffs.motw==false)")
case('Cross-class profile copy remains refused',"B:SaveClassSetup(); local source=B.profileDB:GetCurrentProfile(); local character=B.profileDB.keys.char; B:CreateSettingsProfile('Other',false); playerClass='PALADIN'; assert(not B:CopySettingsProfile(source,character))")
case('Repeated runtime reads never query group APIs',"B:SyncSituation(); local n=0; IsInRaid=function() n=n+1; return false end; for i=1,100 do B:Preference('buffs'); B:SituationActionCurrent(B.action) end; assert(n==0)")
case('Context transitions retain bounded memory and timers',"B:CancelWakeTimer(); B:CancelRefreshTimer(); collectgarbage('collect'); local start=collectgarbage('count'); local timers=liveTimers(); for i=1,1000 do context=i%2==0 and 'solo' or 'party'; B:SyncSituation() end; collectgarbage('collect'); assert(collectgarbage('count')-start<100 and liveTimers()==timers)")
shaman=setup+"""
playerClass='SHAMAN'; spells={}; book={}; spell(8017,'Rockbiter Weapon',1); spell(8024,'Flametongue Weapon',1)
Enum.WeaponSlot={MainHand=0,OffHand=1}; Enum.ItemEnchantType={None=0,Permanent=1,Temporary=2,Imbue=3}
enchantLists={[0]={},[1]={}}; C_Item.GetWeaponEnchantInfo=function(slot) return enchantLists[slot] end
equipWeapon(16,9001); B.db.weaponApply=true; B.db.weaponChoices.main='rockbiter'; B:InitDB()
B:SetSituationValue('party','weapons','weaponChoices','flametongue','main')
"""
test('Actual Shaman solo Rockbiter and Party Flametongue',shaman+"refresh(); assert(B.action.id==8017); context='party'; refresh(); assert(B.action.id==8024 and B.db.weaponChoices.main=='rockbiter')")
test('Existing imbue requires explicit replacement permission',shaman+"enchantLists[0]={{hasEnchant=true,enchantType=3,enchantID=6,timeLeft=3600000}}; context='party'; refresh(); assert(not B.action); B.db.weaponReplace=true; refresh(); assert(B.action.id==8024)")
cons=setup+"consumables('food'); stock(6888,1248377); stock(250071,1248401); B:SetConsumableChoice(B:ConsumableFamily('food'),6888); B:SetSituationValue('party','consumables','consumableChoices',250071,'food'); "
test('Actual Party consumable action preserves Solo selection',cons+"refresh(); assert(B.action.itemID==6888); context='party'; refresh(); assert(B.action.itemID==250071 and B.db.consumableChoices.food==6888)")
test('Party Auto masks inherited explicit consumable',cons+"B:Options(); B:ChooseConsumable(B:ConsumableFamily('food'),nil,'party'); B.itemPicker.auto.scripts.OnClick(); assert(B:SituationValues('party','consumables').consumableChoices.food==false and B.db.consumableChoices.food==6888); B:InitDB(); assert(B:SituationValues('party','consumables').consumableChoices.food==false)")
for cls in ['DRUID','PALADIN','WARRIOR','HUNTER','ROGUE','WARLOCK','SHAMAN','MAGE','PRIEST']:
 for locale in ['enUS','deDE','frFR','esES','ptBR']:
  test('Integrated selectors '+cls+' '+locale,setup+"playerClass='"+cls+"'; B:InitDB(); B:Options(); assert(#B.options.pages==14); for _,category in ipairs({'buffs','weapons','consumables'}) do local p=B.contextControls[category]; for _,ctx in ipairs({'party','raid','solo'}) do p.buttons[ctx].scripts.OnClick(); assert(B:EditorContext(category)==ctx and B.situationCurrent=='solo') end end",locale=locale)


case('Actual weapon timing slider stores numeric Party override',"B:Options(); B.contextControls.weapons.buttons.party.scripts.OnClick(); local s=B.options.weaponTiming; s.scripts.OnValueChanged(s,120); assert(B:SituationValues('party','weapons').weaponSeconds==120 and B.db.weaponSeconds~=120)")
case('Buff timing slider edits Party baseline only',"B:Options(); B.contextControls.buffs.buttons.party.scripts.OnClick(); local s=B.options.rebuffSlider; s.scripts.OnValueChanged(s,90); assert(B:SituationValues('party','buffs').seconds==90 and B.db.seconds==45)")
case('Consumable timing slider edits Party only',"B:Options(); B.contextControls.consumables.buttons.party.scripts.OnClick(); local s=B.options.consumableRows[1].threshold; s.scripts.OnValueChanged(s,600); assert(B:SituationValues('party','consumables').consumableSeconds.food==600 and B.db.consumableSeconds.food==nil)")
case('Solo changes propagate through a custom live category',"context='party'; B:SetSituationValue('party','weapons','weaponSeconds',120); B:SetSituationValue('solo','weapons','weaponMainHand',false); assert(B:Preference('weaponMainHand')==false and B:Preference('weaponSeconds')==120)")
case('Invalid override keys and classes are dropped',"B.db.situationSettings={version=2,class='DRUID',party={buffs={buffSeconds={bad=false,bok=false,motw=false},priorities={bad=false}},weapons={weaponChoices={invalid=false,main=false}}},raid={}}; B:InitDB(); local v=B:SituationValues('party','buffs'); assert(v.buffSeconds.motw==false and v.buffSeconds.bad==nil and v.buffSeconds.bok==nil and v.priorities==nil); assert(B:SituationValues('party','weapons').weaponChoices.invalid==nil)")
case('Normalization preserves explicit false toggles',"B:SetSituationValue('party','weapons','weaponReminder',false); B:SetSituationValue('party','buffs','buffs',false,'motw'); B:InitDB(); context='party'; refresh(); assert(B:Preference('weaponReminder')==false and not B:Enabled(B:FindBuff('motw')))")
case('Unfinished priority text is discarded on context switch',"B:Options(); local row=B.options.buffRows[1]; B.contextControls.buffs.buttons.party.scripts.OnClick(); assert(B.db.priorities[row.def.key]==nil and not B:SituationValues('party','buffs'))")
case('Returning a choice to Solo removes only that field',"B:SetSituationValue('party','buffs','seconds',90); B:SetSituationValue('party','buffs','buffs',false,'motw'); B:SetSituationValue('party','buffs','seconds',B.db.seconds); local v=B:SituationValues('party','buffs'); assert(v.seconds==nil and v.buffs.motw==false)")
test('Consumable labels show the edited Party choice while Solo is active',cons+"B:Options(); B.contextControls.consumables.buttons.party.scripts.OnClick(); local row=B.options.consumableRows[1]; local info=B:ConsumableItemInfo(250071); assert(row.choice.text==info.name and B.situationCurrent=='solo' and B.db.consumableChoices.food==6888)")
test('Auto preview uses edited preferences rather than active selection',cons+"B:SetSituationValue('party','consumables','consumableChoices',nil,'food'); local family=B:ConsumableFamily('food'); local settings=B:SituationPreview('party','consumables'); local item=B:PreferredConsumableItem(family,settings); assert(item and B:ConsumableChoiceID(family,settings)==nil and B:ConsumableChoiceID(family)==6888)")
case('Inactive enabled consumable setup allows timing edits',"local make=CreateFrame; CreateFrame=function(...) local f=make(...); f.Enable=function(s) s.editable=true end; f.Disable=function(s) s.editable=false end; return f end; B.db.consumablesEnabled=false; B:SetSituationValue('party','consumables','consumablesEnabled',true); B:SetSituationValue('party','consumables','consumableFamilies',true,'food'); B:Options(); B.contextControls.consumables.buttons.party.scripts.OnClick(); assert(B.options.consumableRows[1].threshold.editable==true and B.db.consumablesEnabled==false)")
case('Resetting edited buff toggles uses catalog defaults without changing Solo',"B.db.buffs.motw=false; B.editContexts={buffs='party'}; B:EditorSettings('buffs').buffs={}; local settings=B:SituationPreview('party','buffs'); assert(B:Enabled(B:FindBuff('motw'),settings) and B.db.buffs.motw==false); B:InitDB(); assert(B:Enabled(B:FindBuff('motw'),B:SituationPreview('party','buffs')))")
case('Legacy omitted toggles preserve catalog default behavior',"B.db.buffs.motw=false; B.db.situationSettings={version=1,enabled=true,class='DRUID',party={buffs={buffs={}}}}; B:InitDB(); assert(B:Enabled(B:FindBuff('motw'),B:SituationPreview('party','buffs')) and B.db.buffs.motw==false)")
